#chat-room {
  width: 80%;
  max-width: 600px;
  background-color: #fff;
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
  display: flex;
  flex-direction: column;
}

#chat-window {
  height: 400px;
  overflow-y: auto;
  padding: 10px;
  background-color: #e0e0e0;
  flex-grow: 1;
}

#messages {
  display: flex;
  flex-direction: column;
}

#message-input {
  width: calc(100% - 20px);
  padding: 10px;
  border: none;
  border-top: 1px solid #ccc;
  margin: 5px 0;
}

#send-button {
  width: 100%;
  padding: 10px;
  background-color: #d32f2f;
  color: white;
  border: none;
  cursor: pointer;
}

#send-button:hover {
  background-color: #b71c1c;
}

#messages div {
  padding: 5px;
  margin-bottom: 5px;
  background-color: #f8bbd0;
  border-radius: 5px;
  word-wrap: break-word;
}

#messages div:nth-child(even) {
  background-color: #f48fb1;
}

javascript:
$(document).ready(function() {
  var sendButton = $('#send-button');
  var messageInput = $('#message-input');
  var messagesContainer = $('#messages');

  sendButton.on('click', function() {
    var messageText = messageInput.val();
    var currentUsername = document.getElementById('useremail').textContent;
    if (messageText.trim() !== '' && currentUsername.trim() !== '') {
      $.ajax({
        type: 'POST',
        url: '/skibidi',
        data: JSON.stringify({ username: currentUsername, message: messageText }),
        contentType: 'application/json',
        success: function(response) {
          console.log('Message sent successfully:', response);
          messageInput.val('');
        },
        error: function(error) {
          console.error('Error sending message:', error);
        }
      });
    }
  });

  function scrollToBottom() {
    messagesContainer.scrollTop(messagesContainer.prop("scrollHeight"));
  }

  function handleIncomingMessage(message) {
    var messageElement = $('<div></div>').text(message.username + ': ' + message.message);
    messagesContainer.append(messageElement);
    scrollToBottom();
  }
});

